<?php
require_once __DIR__ . '/../includes/functions.php'; require_login(); require_once __DIR__ . '/../config/database.php';
$userId=(int)current_user()['user_id'];
$stmt=$pdo->prepare('SELECT COUNT(*) FROM user_skills WHERE user_id=?');$stmt->execute([$userId]);$skillCount=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COUNT(*) FROM evidence_submissions WHERE user_id=? AND status='verified'");$stmt->execute([$userId]);$verifiedCount=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare("SELECT COUNT(*) FROM roadmap_items ri JOIN roadmaps r ON r.roadmap_id=ri.roadmap_id WHERE r.user_id=? AND ri.status='completed'");$stmt->execute([$userId]);$completedTasks=(int)$stmt->fetchColumn();
$stmt=$pdo->prepare('SELECT a.assessment_id,a.readiness_score,a.completed_at,j.role_name,j.job_role_id FROM assessments a JOIN job_roles j ON j.job_role_id=a.job_role_id WHERE a.user_id=? AND a.status=\'completed\' ORDER BY a.completed_at DESC LIMIT 1');$stmt->execute([$userId]);$latest=$stmt->fetch();
$stmt=$pdo->prepare('SELECT r.roadmap_id,r.title,r.status,j.role_name,COUNT(ri.item_id) total_items,SUM(ri.status=\'completed\') done_items FROM roadmaps r JOIN job_roles j ON j.job_role_id=r.job_role_id LEFT JOIN roadmap_items ri ON ri.roadmap_id=r.roadmap_id WHERE r.user_id=? AND r.status IN (\'active\',\'paused\') GROUP BY r.roadmap_id ORDER BY r.created_at DESC LIMIT 3');$stmt->execute([$userId]);$roadmaps=$stmt->fetchAll();
$stmt=$pdo->prepare('SELECT e.title,e.status,e.submitted_at,s.skill_name FROM evidence_submissions e JOIN skills s ON s.skill_id=e.skill_id WHERE e.user_id=? ORDER BY e.submitted_at DESC LIMIT 4');$stmt->execute([$userId]);$evidence=$stmt->fetchAll();
$stmt=$pdo->query('SELECT job_role_id,role_name,career_field,short_description FROM job_roles WHERE is_active=1 ORDER BY role_name LIMIT 4');$suggested=$stmt->fetchAll();
$pageTitle='Dashboard';$active='dashboard';include __DIR__.'/../includes/header.php';
?>
